// Benchmark: compare 4 convex-polygon-intersection implementations on randomly
// generated convex polygons.
//
//   1. CGAL intersection with Epeck  (ground truth)
//   2. CGAL intersection with Filtered_kernel<Simple_cartesian<double>>
//      (this is what simplify_SH.cpp uses as IntersectKernel)
//   3. Boost.Geometry bg::intersection
//   4. OpenCV cv::intersectConvexConvex
//
// For each pair of convex polygons (20 vertices each) we:
//   - record wall-time for each method
//   - compute the intersection polygon (as a point list, CCW)
//   - compute its area (CGAL Polygon_2, exact kernel) as the quality metric
//
// Three case spectra are generated per test count:
//   - disjoint         (no intersection; area == 0)
//   - partial overlap  (the typical simplify_SH case)
//   - full containment (P ⊆ Q or Q ⊆ P)
//
// Output: CSV rows on stdout, then a blank line, then a summary table.
//
// Build: see CMakeLists.txt — `test` executable.

#include <CGAL/Exact_predicates_exact_constructions_kernel.h>
#include <CGAL/Filtered_kernel.h>
#include <CGAL/Simple_cartesian.h>
#include <CGAL/Polygon_2.h>
#include <CGAL/convex_hull_2.h>
#include <CGAL/intersections.h>

#include <boost/geometry.hpp>
#include <boost/geometry/geometries/geometries.hpp>
#include <boost/geometry/geometries/point_xy.hpp>

#include <opencv2/core.hpp>
#include <opencv2/imgproc.hpp>

#include <algorithm>
#include <chrono>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <random>
#include <sstream>
#include <string>
#include <vector>

namespace bg = boost::geometry;

// ---------- kernels ----------
using Epeck    = CGAL::Exact_predicates_exact_constructions_kernel;
using Filtered = CGAL::Filtered_kernel<CGAL::Simple_cartesian<double>>;

using EPoint     = Epeck::Point_2;
using EPolygon   = CGAL::Polygon_2<Epeck>;
using ESegment   = Epeck::Segment_2;

using FPoint     = Filtered::Point_2;
using FPolygon   = CGAL::Polygon_2<Filtered>;
using FSegment   = Filtered::Segment_2;

// Boost: use its built-in point type so we don't have to register traits.
using BPoint  = bg::model::d2::point_xy<double>;
using BPoly   = bg::model::polygon<BPoint, true, true>;  // CCW, closed

// ---------- helpers ----------

// Generate a random convex polygon with `n` vertices inside a square of side
// 2*half_extent centered at the origin. Uses the standard "sorted random radii"
// trick that produces a convex polygon when the radii are sorted by angle.
static std::vector<std::pair<double,double>>
random_convex_polygon(int n, double half_extent, std::mt19937& rng) {
    std::uniform_real_distribution<double> angle_dist(0.0, 2.0 * M_PI);
    std::uniform_real_distribution<double> radius_dist(0.0, 1.0);

    std::vector<double> angles(n);
    for (int i = 0; i < n; ++i) angles[i] = angle_dist(rng);
    std::sort(angles.begin(), angles.end());

    std::vector<std::pair<double,double>> pts;
    pts.reserve(n);
    for (int i = 0; i < n; ++i) {
        // Square-root the radius for uniform area distribution, then scale
        // by half_extent to keep the polygon inside the bounding box.
        double r = std::sqrt(radius_dist(rng)) * half_extent;
        pts.emplace_back(r * std::cos(angles[i]), r * std::sin(angles[i]));
    }
    return pts;
}

// Translate a polyline by (dx, dy).
static void translate(std::vector<std::pair<double,double>>& pts,
                      double dx, double dy) {
    for (auto& [x, y] : pts) { x += dx; y += dy; }
}

enum class CaseType { Disjoint, Partial, Containment };

static const char* case_name(CaseType c) {
    switch (c) {
        case CaseType::Disjoint:     return "disjoint";
        case CaseType::Partial:      return "partial";
        case CaseType::Containment:  return "containment";
    }
    return "?";
}

// Build a polygon pair for the requested case type, both CCW, vertices in
// double precision. `out_p`, `out_q` are filled with (x, y) pairs.
static void make_case(CaseType c, int n_verts, double half_extent,
                      std::mt19937& rng,
                      std::vector<std::pair<double,double>>& out_p,
                      std::vector<std::pair<double,double>>& out_q) {
    out_p = random_convex_polygon(n_verts, half_extent, rng);
    switch (c) {
        case CaseType::Disjoint: {
            // Place Q far away from P in a non-overlapping square.
            out_q = random_convex_polygon(n_verts, half_extent, rng);
            translate(out_q, 2.0 * half_extent, 2.0 * half_extent);
            break;
        }
        case CaseType::Partial: {
            // Place Q overlapping ~half of P.
            out_q = random_convex_polygon(n_verts, half_extent * 0.6, rng);
            translate(out_q, half_extent * 0.5, half_extent * 0.3);
            break;
        }
        case CaseType::Containment: {
            // Q is a smaller polygon inside P (we make it, then translate
            // its centroid to the origin of P, which is also the origin).
            out_q = random_convex_polygon(n_verts, half_extent * 0.4, rng);
            // no translation — Q is inside P (both centered at origin)
            break;
        }
    }
}

// Compute area of a CCW polygon given as a list of doubles (closed or open
// is irrelevant — shoelace handles both). Uses Epeck for ground truth so
// that quality numbers are not affected by the candidate method's precision.
static double area_exact(const std::vector<std::pair<double,double>>& pts) {
    if (pts.size() < 3) return 0.0;
    EPolygon poly;
    for (const auto& [x, y] : pts) poly.push_back(EPoint(x, y));
    if (poly.size() < 3) return 0.0;
    return CGAL::to_double(poly.area());
}

// ---------- the 4 methods ----------
//
// Each method returns a vector of (x, y) pairs in CCW order representing the
// (single) intersection polygon, or an empty vector if there is no intersection.
// (Some implementations may emit multiple polygons in pathological cases; for
//  random convex inputs there is at most one.)

// 1. CGAL intersection with Epeck — the ground truth.
static std::vector<std::pair<double,double>>
intersect_cgal_epeck(const std::vector<std::pair<double,double>>& p_pts,
                     const std::vector<std::pair<double,double>>& q_pts) {
    std::vector<EPoint> p, q;
    p.reserve(p_pts.size()); q.reserve(q_pts.size());
    for (const auto& [x, y] : p_pts) p.emplace_back(x, y);
    for (const auto& [x, y] : q_pts) q.emplace_back(x, y);
    std::vector<EPolygon> polys;
    CGAL::intersection(p, q, std::back_inserter(polys));
    std::vector<std::pair<double,double>> out;
    if (polys.empty()) return out;
    for (const auto& v : polys[0].vertices())
        out.emplace_back(CGAL::to_double(v.x()), CGAL::to_double(v.y()));
    return out;
}

// 2. CGAL intersection with Filtered_kernel<Simple_cartesian<double>>.
// This is the same as IntersectKernel in simplify_SH.cpp.
static std::vector<std::pair<double,double>>
intersect_cgal_filtered(const std::vector<std::pair<double,double>>& p_pts,
                        const std::vector<std::pair<double,double>>& q_pts) {
    std::vector<FPoint> p, q;
    p.reserve(p_pts.size()); q.reserve(q_pts.size());
    for (const auto& [x, y] : p_pts) p.emplace_back(x, y);
    for (const auto& [x, y] : q_pts) q.emplace_back(x, y);
    std::vector<FPolygon> polys;
    CGAL::intersection(p, q, std::back_inserter(polys));
    std::vector<std::pair<double,double>> out;
    if (polys.empty()) return out;
    for (const auto& v : polys[0].vertices())
        out.emplace_back(v.x(), v.y());
    return out;
}

// 3. Boost.Geometry intersection.
// Note: bg::intersection fills one or more polygons; we take the first.
static std::vector<std::pair<double,double>>
intersect_boost(const std::vector<std::pair<double,double>>& p_pts,
                const std::vector<std::pair<double,double>>& q_pts) {
    BPoly p, q;
    for (const auto& [x, y] : p_pts) bg::append(p, BPoint(x, y));
    for (const auto& [x, y] : q_pts) bg::append(q, BPoint(x, y));
    std::vector<BPoly> out_polys;
    bg::intersection(p, q, out_polys);
    std::vector<std::pair<double,double>> out;
    if (out_polys.empty()) return out;
    for (const auto& pt : out_polys[0].outer())
        out.emplace_back(bg::get<0>(pt), bg::get<1>(pt));
    return out;
}

// 4. OpenCV cv::intersectConvexConvex.
// Signature: intersectConvexConvex( _p1, _p2, _p12, handleNested )
// Inputs are cv::Mat of shape 1xN. handleNested=true avoids asserting on
// full containment.
static std::vector<std::pair<double,double>>
intersect_opencv(const std::vector<std::pair<double,double>>& p_pts,
                 const std::vector<std::pair<double,double>>& q_pts) {
    cv::Mat p1(static_cast<int>(p_pts.size()), 1, CV_32SC2);
    cv::Mat p2(static_cast<int>(q_pts.size()), 1, CV_32SC2);
    for (size_t i = 0; i < p_pts.size(); ++i)
        p1.at<cv::Vec2i>(static_cast<int>(i), 0) =
            cv::Vec2i(static_cast<int>(std::lround(p_pts[i].first * 1e6)),
                      static_cast<int>(std::lround(p_pts[i].second * 1e6)));
    for (size_t i = 0; i < q_pts.size(); ++i)
        p2.at<cv::Vec2i>(static_cast<int>(i), 0) =
            cv::Vec2i(static_cast<int>(std::lround(q_pts[i].first * 1e6)),
                      static_cast<int>(std::lround(q_pts[i].second * 1e6)));
    cv::Mat p12;
    cv::rotate(p1, p1, cv::ROTATE_90_CLOCKWISE);  // CV expects Nx1 col-major
    cv::rotate(p2, p2, cv::ROTATE_90_CLOCKWISE);
    float area = cv::intersectConvexConvex(p1, p2, p12, true);
    (void)area;
    std::vector<std::pair<double,double>> out;
    if (p12.empty()) return out;
    cv::rotate(p12, p12, cv::ROTATE_90_COUNTERCLOCKWISE);
    for (int i = 0; i < p12.rows; ++i) {
        const cv::Vec2i v = p12.at<cv::Vec2i>(i, 0);
        out.emplace_back(v[0] / 1e6, v[1] / 1e6);
    }
    return out;
}

// ---------- timing helper ----------
template <class F, class... Args>
static double time_call_us(F&& f, Args&&... args) {
    auto t0 = std::chrono::high_resolution_clock::now();
    auto result = f(std::forward<Args>(args)...);
    auto t1 = std::chrono::high_resolution_clock::now();
    (void)result;
    return std::chrono::duration<double, std::micro>(t1 - t0).count();
}

int main(int argc, char** argv) {
    int n_verts   = (argc > 1) ? std::atoi(argv[1]) : 20;
    int n_iters   = (argc > 2) ? std::atoi(argv[2]) : 1000;
    int seed      = (argc > 3) ? std::atoi(argv[3]) : 42;
    double half_extent = (argc > 4) ? std::atof(argv[4]) : 10.0;

    std::mt19937 rng(seed);

    std::cout << "case,"
              << "iter,"
              << "epeck_us,filtered_us,boost_us,opencv_us,"
              << "epeck_area,filtered_area,boost_area,opencv_area\n";

    const std::vector<CaseType> cases = {
        CaseType::Disjoint, CaseType::Partial, CaseType::Containment
    };
    for (auto c : cases) {
        for (int it = 0; it < n_iters; ++it) {
            std::vector<std::pair<double,double>> p_pts, q_pts;
            make_case(c, n_verts, half_extent, rng, p_pts, q_pts);

            // Epeck
            double t_e = time_call_us(intersect_cgal_epeck, p_pts, q_pts);
            auto r_e = intersect_cgal_epeck(p_pts, q_pts);
            double a_e = area_exact(r_e);

            // Filtered
            double t_f = time_call_us(intersect_cgal_filtered, p_pts, q_pts);
            auto r_f = intersect_cgal_filtered(p_pts, q_pts);
            double a_f = area_exact(r_f);

            // Boost
            double t_b = time_call_us(intersect_boost, p_pts, q_pts);
            auto r_b = intersect_boost(p_pts, q_pts);
            double a_b = area_exact(r_b);

            // OpenCV
            double t_o = time_call_us(intersect_opencv, p_pts, q_pts);
            auto r_o = intersect_opencv(p_pts, q_pts);
            double a_o = area_exact(r_o);

            std::cout << case_name(c) << ',' << it << ','
                      << std::fixed << std::setprecision(3)
                      << t_e << ',' << t_f << ',' << t_b << ',' << t_o << ','
                      << a_e << ',' << a_f << ',' << a_b << ',' << a_o << '\n';
        }
    }
    return 0;
}

