// ---------- the 4 methods ----------
//
// Each method returns a vector of (x, y) pairs in CCW order representing the
// (single) intersection polygon, or an empty vector if there is no intersection.
// (Some implementations may emit multiple polygons in pathological cases; for
//  random convex inputs there is at most one.)

// Common O(n + m) convex-convex polygon intersection.
// Templated on the point type so we can run it once with Epeck points
// and once with Filtered<double> points — same algorithm, different
// number types. Uses CGAL's robust orientation predicate and exact
// segment intersection (kernel-dependent).
template <class K>
static std::vector<std::pair<double,double>>
convex_intersect(const std::vector<std::pair<double,double>>& p_pts,
                 const std::vector<std::pair<double,double>>& q_pts) {
    using Point   = typename K::Point_2;
    using Segment = typename K::Segment_2;

    const int n = (int)p_pts.size();
    const int m = (int)q_pts.size();
    if (n < 3 || m < 3) return {};

    std::vector<Point> P(n), Q(m);
    for (int i = 0; i < n; ++i) P[i] = Point(p_pts[i].first,  p_pts[i].second);
    for (int i = 0; i < m; ++i) Q[i] = Point(q_pts[i].first,  q_pts[i].second);

    auto in_poly = [](const Point& p, const std::vector<Point>& poly) {
        const int sz = (int)poly.size();
        for (int i = 0; i < sz; ++i) {
            if (!CGAL::left_turn(poly[i], poly[(i + 1) % sz], p)) return false;
        }
        return true;
    };

    std::vector<Point> out;
    out.reserve(n + m);
    int i = 0, j = 0;
    int i_start = 0, j_start = 0;
    int iters = 0;
    const int max_iters = n + m + 1;
    while (iters++ < max_iters) {
        const Point& Pi  = P[i];
        const Point& Pi1 = P[(i + 1) % n];
        const Point& Qj  = Q[j];
        const Point& Qj1 = Q[(j + 1) % m];

        auto hit = CGAL::intersection(Segment(Pi, Pi1), Segment(Qj, Qj1));
        if (hit && std::holds_alternative<Point>(*hit)) {
            const Point& x = std::get<Point>(*hit);
            if (out.empty() || !(out.back() == x)) out.push_back(x);
        }

        const auto cp = CGAL::cross_product(Pi1 - Pi, Qj1 - Pi);

        if (CGAL::to_double(cp) >= 0) {
            if (in_poly(Qj1, P)) {
                if (out.empty() || !(out.back() == Qj1)) out.push_back(Qj1);
            }
            j = (j + 1) % m;
        }
        if (CGAL::to_double(cp) <= 0) {
            if (in_poly(Pi1, Q)) {
                if (out.empty() || !(out.back() == Pi1)) out.push_back(Pi1);
            }
            i = (i + 1) % n;
        }

        if (i == i_start && j == j_start) break;
        if (iters == 1) { i_start = i; j_start = j; }
    }

    if (out.size() < 3) return {};
    std::vector<Point> hull;
    CGAL::convex_hull_2(out.begin(), out.end(), std::back_inserter(hull));
    if (hull.size() < 3) return {};

    std::vector<std::pair<double,double>> result;
    result.reserve(hull.size());
    for (const auto& v : hull) {
        result.emplace_back(CGAL::to_double(v.x()), CGAL::to_double(v.y()));
    }
    return result;
}

