static void convex_polygon_intersection(const Polygon& P, const Polygon& Q,
                                       std::vector<Polygon_with_holes>& result) {
    TIMER("intersection_total");
    {
        TIMER("intersection_convert");
        std::vector<IntersectPoint> P_verts, Q_verts;
        P_verts.reserve(P.size());
        Q_verts.reserve(Q.size());
        for (auto it = P.vertices_begin(); it != P.vertices_end(); ++it) {
            P_verts.push_back(to_intersect(*it));
        }
        for (auto it = Q.vertices_begin(); it != Q.vertices_end(); ++it) {
            Q_verts.push_back(to_intersect(*it));
        }

        const int n = (int)P_verts.size();
        const int m = (int)Q_verts.size();
        if (n < 3 || m < 3) return;

        // O(n + m) convex-convex polygon intersection.
        // Both polygons are CCW. Walk both boundaries simultaneously;
        // at each step advance whichever edge is "ahead" relative to the other.
        std::vector<IntersectPoint> out;
        out.reserve(n + m);
        int i = 0, j = 0;
        int i_start = 0, j_start = 0;
        const int max_iters = n + m + 1;  // safety: terminate after one full tour
        int iters = 0;
        while (iters++ < max_iters) {
            const IntersectPoint& Pi  = P_verts[i];
            const IntersectPoint& Pi1 = P_verts[(i + 1) % n];
            const IntersectPoint& Qj  = Q_verts[j];
            const IntersectPoint& Qj1 = Q_verts[(j + 1) % m];

            // Crossings of the current P-edge and Q-edge
            auto hit = CGAL::intersection(IntersectSegment(Pi, Pi1),
                                          IntersectSegment(Qj, Qj1));
            if (hit && std::holds_alternative<IntersectPoint>(*hit)) {
                const IntersectPoint& x = std::get<IntersectPoint>(*hit);
                if (out.empty() || !(out.back().x() == x.x() && out.back().y() == x.y())) {
                    out.push_back(x);
                }
            }

            // Decide which polygon to advance: compare cross products of the
            // two edge vectors with the vector from Pi to Qj. The polygon whose
            // edge is "more clockwise" (smaller cross product, given CCW input)
            // from the current pair is the one whose next vertex enters next.
            auto cross = [](const IntersectPoint& a, const IntersectPoint& b,
                            const IntersectPoint& c) {
                return (b.x() - a.x()) * (c.y() - a.y())
                     - (b.y() - a.y()) * (c.x() - a.x());
            };
            const long double cp = cross(Pi, Pi1, Qj1);
            if (cp >= 0) {
                // P-edge is "ahead" or aligned: advance Q
                if (point_in_polygon(Qj1, P_verts)) {
                    if (out.empty() || !(out.back().x() == Qj1.x() && out.back().y() == Qj1.y())) {
                        out.push_back(Qj1);
                    }
                }
                j = (j + 1) % m;
            }
            if (cp <= 0) {
                // Q-edge is "ahead" or aligned: advance P
                if (point_in_polygon(Pi1, Q_verts)) {
                    if (out.empty() || !(out.back().x() == Pi1.x() && out.back().y() == Pi1.y())) {
                        out.push_back(Pi1);
                    }
                }
                i = (i + 1) % n;
            }

            if (i == i_start && j == j_start) break;
            if (iters == 1) { i_start = i; j_start = j; }
        }

        if (out.size() < 3) return;

        {
            TIMER("intersection_convex_hull");
            std::vector<IntersectPoint> hull;
            CGAL::convex_hull_2(out.begin(), out.end(), std::back_inserter(hull));
            if (hull.size() < 3) return;

            std::vector<Point> result_verts;
            result_verts.reserve(hull.size());
            for (const auto& hp : hull) {
                result_verts.push_back(from_intersect(hp));
            }
            Polygon inter_poly(result_verts.begin(), result_verts.end());
            if (!inter_poly.is_simple()) return;
            if (inter_poly.is_clockwise_oriented()) inter_poly.reverse_orientation();
            result.push_back(Polygon_with_holes(inter_poly));
        }
    }
}

