// Common O(n*m) convex-convex polygon intersection — mirrors the algorithm
// in simplify_SH.cpp's convex_polygon_intersection, but templated on the
// kernel so we can run it once with Epeck and once with Filtered<double>.
// The algorithm:
//   1. All vertices of P inside Q
//   2. All vertices of Q inside P
//   3. All segment-segment intersections between P-edges and Q-edges
//   4. Take the convex hull of (1)+(2)+(3)
template <class K>
static std::vector<std::pair<double,double>>
convex_intersect(const std::vector<std::pair<double,double>>& p_pts,
                 const std::vector<std::pair<double,double>>& q_pts) {
    using Point   = typename K::Point_2;
    using Segment = typename K::Segment_2;

    const int n = (int)p_pts.size();
    const int m = (int)q_pts.size();
    if (n < 3 || m < 3) return {};

    std::vector<Point> P(n), Q(m);
    for (int i = 0; i < n; ++i) P[i] = Point(p_pts[i].first,  p_pts[i].second);
    for (int i = 0; i < m; ++i) Q[i] = Point(q_pts[i].first,  q_pts[i].second);

    auto in_poly = [](const Point& p, const std::vector<Point>& poly) {
        const int sz = (int)poly.size();
        for (int i = 0; i < sz; ++i) {
            if (!CGAL::left_turn(poly[i], poly[(i + 1) % sz], p)) return false;
        }
        return true;
    };

    auto seg_inter = [](const Point& a, const Point& b,
                        const Point& c, const Point& d) -> std::optional<Point> {
        auto hit = CGAL::intersection(Segment(a, b), Segment(c, d));
        if (hit && std::holds_alternative<Point>(*hit)) {
            return std::get<Point>(*hit);
        }
        return std::nullopt;
    };

    std::vector<Point> candidates;
    auto add_unique = [&](const Point& p) {
        for (const auto& q : candidates) {
            if (q == p) return;
        }
        candidates.push_back(p);
    };

    // 1. P-vertices inside Q
    for (int i = 0; i < n; ++i) {
        if (in_poly(P[i], Q)) add_unique(P[i]);
    }
    // 2. Q-vertices inside P
    for (int j = 0; j < m; ++j) {
        if (in_poly(Q[j], P)) add_unique(Q[j]);
    }
    // 3. Edge-edge intersections
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            auto x = seg_inter(P[i], P[(i + 1) % n], Q[j], Q[(j + 1) % m]);
            if (x) add_unique(*x);
        }
    }

    if (candidates.size() < 3) return {};
    std::vector<Point> hull;
    CGAL::convex_hull_2(candidates.begin(), candidates.end(), std::back_inserter(hull));
    if (hull.size() < 3) return {};

    std::vector<std::pair<double,double>> result;
    result.reserve(hull.size());
    for (const auto& v : hull) {
        result.emplace_back(CGAL::to_double(v.x()), CGAL::to_double(v.y()));
    }
    return result;
}

