                 const std::vector<std::pair<double,double>>& q_pts) {
    using Point   = typename K::Point_2;
    using Segment = typename K::Segment_2;

    const int n = (int)p_pts.size();
    const int m = (int)q_pts.size();
    if (n < 3 || m < 3) return {};

    std::vector<Point> P(n), Q(m);
    for (int i = 0; i < n; ++i) P[i] = Point(p_pts[i].first,  p_pts[i].second);
    for (int i = 0; i < m; ++i) Q[i] = Point(q_pts[i].first,  q_pts[i].second);

    auto in_poly = [](const Point& p, const std::vector<Point>& poly) {
        const int sz = (int)poly.size();
        for (int i = 0; i < sz; ++i) {
            if (!CGAL::left_turn(poly[i], poly[(i + 1) % sz], p)) return false;
        }
        return true;
    };

    std::vector<Point> out;
    out.reserve(n + m);
    int i = 0, j = 0;
    int i_start = 0, j_start = 0;
    int iters = 0;
    const int max_iters = n + m + 1;
    while (iters++ < max_iters) {
        const Point& Pi  = P[i];
        const Point& Pi1 = P[(i + 1) % n];
        const Point& Qj  = Q[j];
        const Point& Qj1 = Q[(j + 1) % m];

        auto hit = CGAL::intersection(Segment(Pi, Pi1), Segment(Qj, Qj1));
        if (hit && std::holds_alternative<Point>(*hit)) {
            const Point& x = std::get<Point>(*hit);
            if (out.empty() || !(out.back() == x)) out.push_back(x);
        }

        // 2D cross product of (Pi -> Pi1) and (Pi -> Qj1). Sign tells us
        // which polygon's edge is "ahead" of the other. Negative means Qj1
        // is to the right of edge Pi->Pi1 (i.e. Q-edge is "more clockwise").
        const auto cpf = [](const Point& a, const Point& b, const Point& c) {
            const double ax = CGAL::to_double(a.x()), ay = CGAL::to_double(a.y());
            const double bx = CGAL::to_double(b.x()), by = CGAL::to_double(b.y());
            const double cx = CGAL::to_double(c.x()), cy = CGAL::to_double(c.y());
            return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
        };
        const double cp = cpf(Pi, Pi1, Qj1);
        if (cp >= 0) {
            if (in_poly(Qj1, P)) {
                if (out.empty() || !(out.back() == Qj1)) out.push_back(Qj1);
