        if (cp <= 0) {
            if (in_poly(Pi1, Q)) {
                if (out.empty() || !(out.back() == Pi1)) out.push_back(Pi1);
            }
            i = (i + 1) % n;
        }

        if (i == i_start && j == j_start) break;
        if (iters == 1) { i_start = i; j_start = j; }
    }

    if (out.size() < 3) return {};
    std::vector<Point> hull;
    CGAL::convex_hull_2(out.begin(), out.end(), std::back_inserter(hull));
    if (hull.size() < 3) return {};

    std::vector<std::pair<double,double>> result;
    result.reserve(hull.size());
    for (const auto& v : hull) {
        result.emplace_back(CGAL::to_double(v.x()), CGAL::to_double(v.y()));
    }
    return result;
}

