// Compute area of a polygon given as a list of doubles (closed or open
// is irrelevant — shoelace handles both). Uses Epeck for ground truth so
// that quality numbers are not affected by the candidate method's precision.
// Returns the absolute area: candidate methods may emit CW or CCW output
// (e.g. OpenCV emits CW by default), and we want a uniform magnitude.
static double area_exact(const std::vector<std::pair<double,double>>& pts) {
    if (pts.size() < 3) return 0.0;
    CGAL::Polygon_2<Epeck> poly;
    for (const auto& [x, y] : pts) poly.push_back(Epeck::Point_2(x, y));
    if (poly.size() < 3) return 0.0;
    return std::abs(CGAL::to_double(poly.area()));
}

