// Generate a random convex polygon with `n` vertices inside a square of side
// 2*half_extent centered at the origin. Strategy:
//   - draw 4*n random points in the bounding box
//   - take the convex hull
//   - sample `n` of the hull vertices in order
// This is guaranteed to produce a strictly convex simple polygon (assuming
// the hull has at least n+2 vertices, which it almost always will).
static std::vector<std::pair<double,double>>
random_convex_polygon(int n, double half_extent, std::mt19937& rng) {
    std::uniform_real_distribution<double> coord(-half_extent, half_extent);

    std::vector<std::pair<double,double>> pts;
    pts.reserve(4 * n);
    for (int i = 0; i < 4 * n; ++i) {
        pts.emplace_back(coord(rng), coord(rng));
    }
    std::vector<std::pair<double,double>> hull;
    // CGAL expects its own point type for convex_hull_2.
    {
        using K = CGAL::Simple_cartesian<double>;
        std::vector<K::Point_2> cgal_in;
        cgal_in.reserve(pts.size());
        for (const auto& [x, y] : cgal_in.size() ? cgal_in : cgal_in) {}
        // Build input.
        for (const auto& [x, y] : pts) cgal_in.emplace_back(x, y);
        std::vector<K::Point_2> cgal_out;
        CGAL::convex_hull_2(cgal_in.begin(), cgal_in.end(), std::back_inserter(cgal_out));
        for (const auto& p : cgal_out) {
            hull.emplace_back(CGAL::to_double(p.x()), CGAL::to_double(p.y()));
        }
    }

    if (hull.size() <= n) return hull;

    // Sample `n` vertices of the hull, evenly spaced by index, preserving order.
    std::vector<std::pair<double,double>> out;
    out.reserve(n);
    const size_t step = hull.size() / n;
    for (int i = 0; i < n; ++i) {
        out.push_back(hull[i * step % hull.size()]);
    }
    return out;
}

