// Fast alternative: pure double, no CGAL kernel calls, no long-double, no Epeck.
// Same signature as intersect_sh. Drop-in replacement — change the call site
// to call intersect_sh_double instead of intersect_sh.
static void intersect_sh_double(const Polygon& subject, const Polygon& clip,
                               std::back_insert_iterator<std::vector<Polygon_with_holes>> result) {
    TIMER("intersect_sh_double");
    auto to_d = [](const Point& p) {
        return std::make_pair(CGAL::to_double(p.x()), CGAL::to_double(p.y()));
    };
    std::vector<std::pair<double,double>> P, Q;
    P.reserve(subject.size()); Q.reserve(clip.size());
    for (auto it = subject.vertices_begin(); it != subject.vertices_end(); ++it) P.push_back(to_d(*it));
    for (auto it = clip.vertices_begin(); it != clip.vertices_end(); ++it) Q.push_back(to_d(*it));

    auto h = convex_intersect_double(P, Q);
    if (h.size() < 3) return;

    std::vector<Point> verts;
    verts.reserve(h.size());
    for (auto& p : h) verts.emplace_back(p.first, p.second);
    Polygon inter_poly(verts.begin(), verts.end());
    if (inter_poly.is_simple() && !inter_poly.is_clockwise_oriented())
        *result++ = Polygon_with_holes(inter_poly);
}

