// Fast convex-convex intersection on plain double. No CGAL kernel overhead.
// Both polygons must be convex and CCW. Returns empty if disjoint.
static std::vector<std::pair<double,double>> convex_intersect_double(
    const std::vector<std::pair<double,double>>& P,
    const std::vector<std::pair<double,double>>& Q) {
    const int n = (int)P.size(), m = (int)Q.size();
    if (n < 3 || m < 3) return {};
    auto cross = [](const std::pair<double,double>& O,
                    const std::pair<double,double>& A,
                    const std::pair<double,double>& B) {
        return (A.first - O.first) * (B.second - O.second) -
               (A.second - O.second) * (B.first - O.first);
    };
    auto next = [&](int i, int n) { return (i + 1) % n; };
    auto point_in = [](const std::pair<double,double>& p,
                       const std::vector<std::pair<double,double>>& poly) {
        int n = (int)poly.size();
        if (n < 3) return false;
        bool inside = false;
        for (int i = 0, j = n - 1; i < n; j = i++) {
            const auto& pi = poly[i], &pj = poly[j];
            if ((pi.second > p.second) != (pj.second > p.second) &&
                p.first < (pj.first - pi.first) * (p.second - pi.second) /
                          (pj.second - pi.second) + pi.first)
                inside = !inside;
        }
        return inside;
    };
    auto seg_intersect = [](const std::pair<double,double>& a1,
                            const std::pair<double,double>& a2,
                            const std::pair<double,double>& b1,
                            const std::pair<double,double>& b2)
        -> std::optional<std::pair<double,double>> {
        double x1 = a1.first, y1 = a1.second;
        double x2 = a2.first, y2 = a2.second;
        double x3 = b1.first, y3 = b1.second;
        double x4 = b2.first, y4 = b2.second;
        double d = (x1-x2)*(y3-y4) - (y1-y2)*(x3-x4);
        if (std::fabs(d) < 1e-18) return std::nullopt;
        double t = ((x1-x3)*(y3-y4) - (y1-y3)*(x3-x4)) / d;
        double u = -((x1-x2)*(y1-y3) - (y1-y2)*(x1-x3)) / d;
        if (t < 0 || t > 1 || u < 0 || u > 1) return std::nullopt;
        return std::make_pair(x1 + t*(x2-x1), y1 + t*(y2-y1));
    };
    std::vector<std::pair<double,double>> output;
    int i = 0, j = 0;
    int loop = 0;
    const int max_iter = 2 * (n + m);
    while (loop++ < max_iter) {
        double cross_val = cross(P[next(i, n)], P[i], Q[next(j, m)], Q[j]);
        // (signature above uses 3-arg form; use 2-arg here for clarity)
        cross_val = (P[next(i, n)].first - P[i].first) * (Q[next(j, m)].second - Q[j].second) -
                    (P[next(i, n)].second - P[i].second) * (Q[next(j, m)].first - Q[j].first);
        if (point_in(P[i], Q)) output.push_back(P[i]);
        if (point_in(Q[j], P)) output.push_back(Q[j]);
        auto inter = seg_intersect(P[i], P[next(i, n)], Q[j], Q[next(j, m)]);
        if (inter) output.push_back(*inter);
        bool advance_i;
        if (cross_val >= 0) {
            double area_i = std::fabs(cross(P[i], P[next(i, n)], Q[j]));
            double area_j = std::fabs(cross(P[i], Q[j], Q[next(j, m)]));
            advance_i = area_i > area_j;
        } else {
            advance_i = false;
        }
        if (advance_i) i = next(i, n); else j = next(j, m);
        if (i == 0 && j == 0) break;
    }
    if (output.size() < 3) return {};
    // Deduplicate
    std::sort(output.begin(), output.end());
    output.erase(std::unique(output.begin(), output.end(),
        [](const auto& a, const auto& b) {
            return std::fabs(a.first - b.first) < 1e-9 &&
                   std::fabs(a.second - b.second) < 1e-9;
        }), output.end());
    if (output.size() < 3) return {};
    // Convex hull (Andrew's monotone chain)
    std::sort(output.begin(), output.end());
    std::vector<std::pair<double,double>> h;
    int lower = 0;
    for (auto& p : output) {
        while (h.size() >= 2 && cross(h[h.size()-2], h.back(), p) <= 1e-12) h.pop_back();
        h.push_back(p);
    }
    lower = (int)h.size() + 1;
    for (auto it = output.rbegin(); it != output.rend(); ++it) {
        while ((int)h.size() >= lower && cross(h[h.size()-2], h.back(), *it) <= 1e-12) h.pop_back();
        h.push_back(*it);
    }
    h.pop_back();
    if (h.size() < 3) return {};
    return h;
}

// Original: Epeck kernel + filtered intersection kernel + convex hull

// Fast convex-convex intersection on plain double. No CGAL kernel overhead.
// Both polygons must be convex and CCW. Returns empty if disjoint.
static std::vector<std::pair<double,double>> convex_intersect_double(
    const std::vector<std::pair<double,double>>& P,
    const std::vector<std::pair<double,double>>& Q) {
    int n = (int)P.size(), m = (int)Q.size();
    if (n < 3 || m < 3) return {};

    auto cross = [](const std::pair<double,double>& o,
                    const std::pair<double,double>& a,
                    const std::pair<double,double>& b) {
        return (a.first - o.first) * (b.second - o.second) -
               (a.second - o.second) * (b.first - o.first);
    };
    auto in_convex = [&](const std::vector<std::pair<double,double>>& R,
                         const std::pair<double,double>& q) {
        for (int i = 0, sz = (int)R.size(); i < sz; i++)
            if (cross(R[i], R[(i+1)%sz], q) < -1e-12) return false;
        return true;
    };
    auto seg_inter = [](const std::pair<double,double>& a,
                        const std::pair<double,double>& b,
                        const std::pair<double,double>& c,
                        const std::pair<double,double>& d,
                        std::pair<double,double>& out) {
        double x1=a.first,y1=a.second,x2=b.first,y2=b.second;
        double x3=c.first,y3=c.second,x4=d.first,y4=d.second;
        double den = (x1-x2)*(y3-y4) - (y1-y2)*(x3-x4);
        if (std::abs(den) < 1e-15) return false;
        double t = ((x1-x3)*(y3-y4) - (y1-y3)*(x3-x4)) / den;
        out = {x1 + t*(x2-x1), y1 + t*(y2-y1)};
        return true;
    };

    std::vector<std::pair<double,double>> cand;
    cand.reserve(n + m);
    for (int i = 0; i < n; i++) if (in_convex(Q, P[i])) cand.push_back(P[i]);
    for (int j = 0; j < m; j++) if (in_convex(P, Q[j])) cand.push_back(Q[j]);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) {
            std::pair<double,double> ip;
            if (seg_inter(P[i], P[(i+1)%n], Q[j], Q[(j+1)%m], ip))
                cand.push_back(ip);
        }

    // dedup with O(k^2) for tiny k
    std::vector<std::pair<double,double>> u;
    u.reserve(cand.size());
    for (auto& p : cand) {
        bool seen = false;
        for (auto& q : u)
            if (std::abs(p.first-q.first) < 1e-9 && std::abs(p.second-q.second) < 1e-9)
                { seen = true; break; }
        if (!seen) u.push_back(p);
    }
    if (u.size() < 3) return {};

    // monotone chain convex hull
    std::sort(u.begin(), u.end(), [](const auto& a, const auto& b){
        return a.first < b.first || (a.first == b.first && a.second < b.second);
    });
    std::vector<std::pair<double,double>> h;
    for (auto& p : u) {
        while (h.size() >= 2 && cross(h[h.size()-2], h.back(), p) <= 1e-12) h.pop_back();
        h.push_back(p);
    }
    size_t lower = h.size() + 1;
    for (auto it = u.rbegin(); it != u.rend(); ++it) {
        while (h.size() >= lower && cross(h[h.size()-2], h.back(), *it) <= 1e-12) h.pop_back();
        h.push_back(*it);
    }
    h.pop_back();
    if (h.size() < 3) return {};
    return h;
}

